export interface GrammarCorrection {
  original: string;
  replacement: string;
  reason: string;
}

export interface GrammarResult {
  correctedText: string;
  corrections: GrammarCorrection[];
}

export enum ToolType {
  COUNTER = 'counter',
  GRAMMAR = 'grammar',
