  const [styles, setStyles] = useState<{name: string, content: string, key: string}[]>([]);

  useEffect(() => {
    setStyles(getCalligraphyStyles(inputText));
  }, [inputText]);

  const copy = (content: string) => {
    navigator.clipboard.writeText(content);
