export const getStats = (text: string) => {
  const trimmed = text.trim();
  if (!trimmed) {
    return { words: 0, characters: 0, sentences: 0, paragraphs: 0 };
  }

  // Use Intl.Segmenter for accurate multilingual segmentation (standard in modern browsers)
  // This handles languages like Hindi (using ।), Chinese/Japanese (no spaces), etc.

  let words = 0;
  let sentences = 0;

  try {
    // Word counting
    const wordSegmenter = new Intl.Segmenter(undefined, { granularity: 'word' });
    const wordSegments = wordSegmenter.segment(text);
    for (const segment of wordSegments) {
      if (segment.isWordLike) words++;
    }

    // Sentence counting
    const sentenceSegmenter = new Intl.Segmenter(undefined, { granularity: 'sentence' });
    const sentenceSegments = sentenceSegmenter.segment(text);
    for (const _ of sentenceSegments) {
      sentences++;
    }
  } catch (e) {
    // Fallback for environments where Intl.Segmenter might not be available
    words = trimmed.split(/\s+/).length;
    // More comprehensive regex for sentences including Hindi/Sanskrit (।), CJK (。), etc.
    sentences = trimmed.split(/[.!?।॥。？！\n]+/).filter(s => s.trim().length > 0).length;
  }

  const characters = text.length;
  const paragraphs = text.split(/\n+/).filter(p => p.trim().length > 0).length;

  return { words, characters, sentences, paragraphs };
};

export const capitalizeSentences = (text: string) => {
  // Matches first letter after start of string or after sentence terminators (. ! ? । 。) followed by whitespace
  // Added Hindi Purna Viram and CJK full stop support to capitalization logic
  return text.replace(/(^|[.!?।。]\s+)([a-zа-я])/gi, (match, separator, char) => {
    return separator + char.toUpperCase();
  });
};

