export const getCalligraphyStyles = (text: string) => {
  const styleConfigs = [
    { name: 'Elegant Script', key: 'script' },
    { name: 'Bold Minimalist', key: 'bold' },
    { name: 'Slanted Italic', key: 'italic' },
    { name: 'Modern Mono', key: 'mono' },
    { name: 'Royal Double', key: 'double' },
    { name: 'Classic Fraktur', key: 'fraktur' },
    { name: 'Circled Classic', key: 'circled' }
  ];

  return styleConfigs.map(style => {
    const map = calligraphyMaps[style.key as keyof typeof calligraphyMaps];
    const converted = text.split('').map(char => (map as any)?.[char] || char).join('');
    return { ...style, content: converted };
  });
};

export const getStats = (text: string) => {
  const trimmed = text.trim();
  if (!trimmed) {
    return { words: 0, characters: 0, sentences: 0, paragraphs: 0 };
  }

  let words = 0;
  let sentences = 0;

  if (typeof Intl !== 'undefined' && (Intl as any).Segmenter) {
    try {
      const wordSegmenter = new (Intl as any).Segmenter(undefined, { granularity: 'word' });
      const wordSegments = wordSegmenter.segment(text);
      for (const segment of wordSegments) {
        if (segment.isWordLike) words++;
      }

      const sentenceSegmenter = new (Intl as any).Segmenter(undefined, { granularity: 'sentence' });
      const sentenceSegments = sentenceSegmenter.segment(text);
      for (const _ of sentenceSegments) {
        sentences++;
      }
    } catch (e) {
      words = trimmed.split(/\s+/).length;
      sentences = trimmed.split(/[.!?।॥。？！\n]+/).filter(s => s.trim().length > 0).length;
    }
  } else {
    words = (text.match(/[\p{L}\p{N}]+/gu) || []).length;
    sentences = trimmed.split(/[.!?।॥。？！\n]+/).filter(s => s.trim().length > 0).length;
  }

  const characters = text.length;
  const paragraphs = text.split(/\n+/).filter(p => p.trim().length > 0).length;

  return { words, characters, sentences, paragraphs };
};

export const capitalizeSentences = (text: string) => {
  /**
   * Unicode-aware capitalization.
   * Matches start of string or sentence terminators followed by whitespace, then any lowercase Unicode letter.
   */
  return text.replace(/(^|[.!?।。]\s+)(\p{Ll})/gu, (match, separator, char) => {
    return separator + char.toUpperCase();
  });
};

import { GoogleGenAI, Type } from "@google/genai";
import { GrammarResult } from "../types";

export const checkGrammar = async (text: string, language: string): Promise<GrammarResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Proofread and fix the following text in ${language}. Return the corrected text and a list of specific grammatical improvements. Text: "${text}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          correctedText: { type: Type.STRING },
          corrections: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                original: { type: Type.STRING },
                replacement: { type: Type.STRING },
                reason: { type: Type.STRING }
              },
              required: ['original', 'replacement', 'reason']
            }
          }
        },
        required: ['correctedText', 'corrections']
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

import { GoogleGenAI, Modality } from "@google/genai";

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const generateSpeech = async (text: string, voiceName: string = 'Kore'): Promise<void> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName }
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("No audio data received");

  const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const audioBuffer = await decodeAudioData(
    decode(base64Audio),
    outputAudioContext,
    24000,
    1,
  );

  const source = outputAudioContext.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(outputAudioContext.destination);
  source.start();
};

