import { GoogleGenAI, Type } from "@google/genai";

export interface SimilarityResult {
  lexicalScore: number;
  semanticScore: number;
  explanation: string;
}

/**
 * Calculates Lexical Similarity using Jaccard Index (word-based).
 */
const calculateLexicalSimilarity = (textA: string, textB: string): number => {
  const wordsA = new Set(textA.toLowerCase().match(/[\p{L}\p{N}]+/gu) || []);
  const wordsB = new Set(textB.toLowerCase().match(/[\p{L}\p{N}]+/gu) || []);

  if (wordsA.size === 0 && wordsB.size === 0) return 100;
  if (wordsA.size === 0 || wordsB.size === 0) return 0;

  const intersection = new Set([...wordsA].filter(x => wordsB.has(x)));
  const union = new Set([...wordsA, ...wordsB]);

  return Math.round((intersection.size / union.size) * 100);
};

/**
 * Calculates Semantic Similarity using Gemini AI.
 */
export const checkSimilarity = async (textA: string, textB: string): Promise<SimilarityResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const lexical = calculateLexicalSimilarity(textA, textB);

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Compare the following two texts for semantic similarity (meaning). 
    Text A: "${textA}"
    Text B: "${textB}"

    Return a score from 0 to 100 where 100 means identical meaning and 0 means completely different. 
    Also provide a very brief one-sentence explanation of why they are or aren't similar.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          semanticScore: { type: Type.NUMBER, description: "Score from 0 to 100" },
          explanation: { type: Type.STRING }
        },
        required: ['semanticScore', 'explanation']
      }
    }
  });

  const geminiData = JSON.parse(response.text || '{"semanticScore": 0, "explanation": "Error calculating similarity."}');

  return {
    lexicalScore: lexical,
    semanticScore: geminiData.semanticScore,
    explanation: geminiData.explanation
  };
};

