/**
 * Calculates Lexical Similarity using Jaccard Index.
 * Measures the overlap of unique words between two sets.
 */
const calculateJaccardIndex = (textA: string, textB: string): number => {
  const wordsA = new Set(textA.toLowerCase().match(/[\p{L}\p{N}]+/gu) || []);
  const wordsB = new Set(textB.toLowerCase().match(/[\p{L}\p{N}]+/gu) || []);

  if (wordsA.size === 0 && wordsB.size === 0) return 100;
  if (wordsA.size === 0 || wordsB.size === 0) return 0;

  const intersection = new Set([...wordsA].filter(x => wordsB.has(x)));
  const union = new Set([...wordsA, ...wordsB]);

  return Math.round((intersection.size / union.size) * 100);
};

/**
 * Calculates Semantic Similarity using Cosine Similarity on word frequency vectors.
 * Measures the "direction" of the word usage, identifying how similar the content structure is.
 */
const calculateCosineSimilarity = (textA: string, textB: string): number => {
  const wordsA = textA.toLowerCase().match(/[\p{L}\p{N}]+/gu) || [];
  const wordsB = textB.toLowerCase().match(/[\p{L}\p{N}]+/gu) || [];

  if (wordsA.length === 0 && wordsB.length === 0) return 100;
  if (wordsA.length === 0 || wordsB.length === 0) return 0;

  const freqA: Record<string, number> = {};
  const freqB: Record<string, number> = {};
  const vocab = new Set<string>();

  wordsA.forEach(w => { freqA[w] = (freqA[w] || 0) + 1; vocab.add(w); });
  wordsB.forEach(w => { freqB[w] = (freqB[w] || 0) + 1; vocab.add(w); });

  let dotProduct = 0;
  let magA = 0;
  let magB = 0;

  vocab.forEach(word => {
    const a = freqA[word] || 0;
    const b = freqB[word] || 0;
    dotProduct += a * b;
    magA += a * a;
    magB += b * b;
  });

  const similarity = dotProduct / (Math.sqrt(magA) * Math.sqrt(magB));
  return Math.round(similarity * 100);
};

/**
 * Compares two texts using algorithmic functions.
 */
export const checkSimilarity = async (textA: string, textB: string): Promise<SimilarityResult> => {
  // Simulating small delay to maintain UI loading state experience
  await new Promise(resolve => setTimeout(resolve, 600));

  const lexical = calculateJaccardIndex(textA, textB);
  const semantic = calculateCosineSimilarity(textA, textB);

