    explanation: explanation
  };
};

export interface SimilarityResult {
  lexicalScore: number;
  semanticScore: number;
  explanation: string;
}

/**
 * Calculates Levenshtein Distance.
 * Measures the minimum number of single-character edits required to change one string into another.
 */
const getLevenshteinDistance = (a: string, b: string): number => {
  const tmp = [];
  for (let i = 0; i <= a.length; i++) {
    tmp[i] = [i];
  }
  for (let j = 0; j <= b.length; j++) {
    tmp[0][j] = j;
  }
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      tmp[i][j] = Math.min(
        tmp[i - 1][j] + 1,
        tmp[i][j - 1] + 1,
        tmp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)
      );
    }
  }
  return tmp[a.length][b.length];
};

/**
 * Calculates Sorensen-Dice Coefficient on character bigrams.
 * This is widely used in string similarity algorithms to find likeness
 * because it accounts for sub-string matches and character clusters.
 */
const getSorensenDice = (a: string, b: string): number => {
  const getBigrams = (str: string) => {
    const bigrams = new Set<string>();
    for (let i = 0; i < str.length - 1; i++) {
      bigrams.add(str.substring(i, i + 2));
    }
    return bigrams;
  };

  const aBigrams = getBigrams(a.toLowerCase());
  const bBigrams = getBigrams(b.toLowerCase());

  if (aBigrams.size === 0 && bBigrams.size === 0) return 1;

  let intersection = 0;
  for (const bigram of aBigrams) {
    if (bBigrams.has(bigram)) {
      intersection++;
    }
  }

  return (2 * intersection) / (aBigrams.size + bBigrams.size);
};

/**
 * Calculates Lexical Similarity using Jaccard Index (word-based overlap).
 */
const calculateJaccardIndex = (textA: string, textB: string): number => {
  const wordsA = new Set(textA.toLowerCase().match(/[\p{L}\p{N}]+/gu) || []);
  const wordsB = new Set(textB.toLowerCase().match(/[\p{L}\p{N}]+/gu) || []);

  if (wordsA.size === 0 && wordsB.size === 0) return 100;
  if (wordsA.size === 0 || wordsB.size === 0) return 0;

  const intersection = new Set([...wordsA].filter(x => wordsB.has(x)));
  const union = new Set([...wordsA, ...wordsB]);

  return Math.round((intersection.size / union.size) * 100);
};

/**
 * Compares two texts using robust algorithmic similarity functions.
 */
export const checkSimilarity = async (textA: string, textB: string): Promise<SimilarityResult> => {
  // Simulating small delay to maintain UI UX consistency
  await new Promise(resolve => setTimeout(resolve, 600));

  const a = textA.trim();
  const b = textB.trim();

  // 1. Lexical Score (Standard Jaccard Word Overlap)
  const lexical = calculateJaccardIndex(a, b);

  // 2. Semantic Score (Hybrid Algorithmic Approach)
  // Dice coefficient on character clusters provides an excellent fuzzy comparison
  const dice = getSorensenDice(a, b);

  // Normalized Levenshtein measures structural and character-position similarity
  const levDist = getLevenshteinDistance(a, b);
  const maxLen = Math.max(a.length, b.length);
  const levSim = maxLen === 0 ? 1 : (maxLen - levDist) / maxLen;

  // Weighted blend for a result that feels more "human-accurate" for string comparison
  const score = (dice * 0.75) + (levSim * 0.25);
  const semantic = Math.round(score * 100);

  let explanation = "";
  if (semantic > 80) {
    explanation = "The texts share a very high degree of content structure and character patterns.";
  } else if (semantic > 50) {
    explanation = "The texts have moderate overlap in their vocabulary and phrasing patterns.";
  } else if (semantic > 20) {
    explanation = "The texts appear to be quite different with few shared linguistic features.";
  } else {
    explanation = "The texts are fundamentally different in character composition and structure.";
  }

  return {
    lexicalScore: lexical,
    semanticScore: semantic,
    explanation: explanation
  };
};

